Зависимости: uiautomation (просмотр дерева и клики), Pillow (скриншоты).
Индексы элементов короткоживущие — после каждого действия дерево нужно читать заново.
"""

from __future__ import annotations

import time

import uiautomation as auto
from PIL import ImageGrab

from guard import Denied, Guard

GuardCls = Guard

WAIT = 0.4


# --- чтение состояния ---------------------------------------------------

def list_windows() -> list[dict]:
    """Все видимые окна верхнего уровня."""
    out = []
    for w in auto.GetControlTreeControl():
        try:
            if not w.IsOffscreen() and w.Name:
                out.append({
                    "title": w.Name,
                    "class": w.ClassName,
                    "handle": w.NativeWindowHandle,
                    "process": w.ProcessId,
                    "rect": w.BoundingRectangle,
                })
        except Exception:
            continue
    return out


def _find(title_or_class: str):
    # сначала точное совпадение заголовка
    for w in auto.GetControlTreeControl():
        if w.Name == title_or_class:
            return w
    # затем частичное
    for w in auto.GetControlTreeControl():
        if title_or_class.lower() in (w.Name or "").lower():
            return w
    # затем по классу окна
    for w in auto.GetControlTreeControl():
        if (w.ClassName or "") == title_or_class:
            return w
    raise LookupError(f"Окно не найдено: {title_or_class}")


def _walk(ctrl, depth: int = 0, max_depth: int = 12, limit: int = 400):
    """Обход дерева с индексами для последующих действий."""
    nodes = []
    stack = [(ctrl, 0)]
    while stack and len(nodes) < limit:
        node, d = stack.pop(0)
        try:
            if d <= max_depth:
                nodes.append((len(nodes), node, d))
            if d < max_depth:
                kids = node.GetChildren()
                for k in reversed(kids):
                    stack.insert(0, (k, d + 1))
        except Exception:
            continue
    return nodes


def dump(title_or_class: str, max_depth: int = 10, limit: int = 300) -> dict:
    """Снимок окна: элементы с индексами + скриншот."""
    win = _find(title_or_class)
    nodes = _walk(win, max_depth=max_depth, limit=limit)
    elements = []
    for idx, node, depth in nodes:
        try:
            elements.append({
                "index": idx,
                "depth": depth,
                "name": (node.Name or "")[:90],
                "type": node.ControlTypeName,
                "class": node.ClassName,
                "enabled": node.IsEnabled,
                "rect": node.BoundingRectangle,
            })
        except Exception:
            continue
    return {
        "window": win.Name,
        "class": win.ClassName,
        "element_count": len(elements),
        "elements": elements,
        "screenshot": screenshot(win.Name),
    }


def print_tree(state: dict, max_depth: int = 6, only_named: bool = True) -> None:
    print(f"ОКНО: {state['window']}  ({state['element_count']} элементов)")
    for e in state["elements"]:
        if only_named and not e["name"].strip():
            continue
        if e["depth"] > max_depth:
            continue
        flag = "" if e["enabled"] else " [disabled]"
        print(f"  [{e['index']:>3}] {'  ' * e['depth']}{e['type']:<14} {e['name']}{flag}")


def _by_index(title_or_class: str, index: int):
    win = _find(title_or_class)
    nodes = _walk(win, max_depth=14, limit=800)
    if index < 0 or index >= len(nodes):
        raise LookupError(f"Индекс {index} вне диапазона (0..{len(nodes) - 1})")
    return win, nodes[index][1]


